Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      if Z.eqb pc PC_SM then
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_SM
                                  && ((Nat.eqb i 0 && Nat.eqb j 2 && CBA.regions_eqb (CC.cp_F c) CPF0) || (Nat.eqb i 1 && Nat.eqb j 3 && CBA.regions_eqb (CC.cp_F c) CPF1))
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 512 1 (nth i G.BLS []) (nth i FFS []) [] (List.filter (sm_ok ps i) (CC.cp_know cj)) None c ps cj
                                             (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => (Nat.eqb (CH2.ci_nx ci) 48 && Z.eqb (CH2.ci_csp ci) (-96))%bool | None => false end)%bool
                    | None => false end
        | None => false end
      else if Z.eqb pc PC_VISIT then      (* [comment removed for export] *)
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_VISIT && Nat.eqb i 2 && Nat.eqb j 4 && Nat.ltb 53 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) CPF2
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && CHA.frames_eqb (nth j FFS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI XKA.VIS 0 [] (nth i FFS []) WENC NEWS_F (Some (ELit 1)) c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => Z.eqb (CH2.ci_csp ci) (-96) | None => false end
                                  && has cells (KWord (SA FE 56) 8 FLE) && CL.ps_reg_is ps 10 VE && CL.ps_reg_is ps 11 (ELit 1)
                                  && has cells (KZero (SA (CHA.SRL3 VE) SBz) (ELit 51)) && has cells (KZero (SA (CHA.SRL3 S2E) SBz) (ELit 3)))%bool
                    | None => false end
        | None => false end
      else if Z.eqb pc PC_ERRH then
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_ERRH && Nat.eqb i 2 && Nat.leb 5 j && Nat.leb j 7 && Nat.ltb 53 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) CPF2
                                  && CC.has_cell (CC.cp_know c) KZF
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 16 0 [] (nth i FFS []) [] NEWS_F None c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => Z.eqb (CH2.ci_csp ci) (-96) | None => false end
                                  && CL.ps_reg_is ps 11 (EAlu Instr.ALU_ADD FE (ELit 32))
                                  && has cells (KWord (SA FE 32) 4 (ELit 11)) && has cells (KWord (SA (CHA.SRL3 FE) (SBz + 4)) 1 (ELit 4)) && has cells (KWord (SA FE 56) 8 FLE))%bool
                    | None => false end
        | None => false end
      else if Z.eqb pc PC_SETEC then
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_SETEC && Nat.leb 5 i && Nat.leb i 7 && Nat.eqb j (i + 3) && Nat.ltb 53 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) CPF2
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 1024 0 [] (nth i FFS []) SETEC_W NEWS_F None c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => Z.eqb (CH2.ci_csp ci) (-96) | None => false end
                                  && CL.ps_reg_is ps 10 EE && CL.ps_reg_is ps 11 (ELit 11) && has cells (KWord (SA FE 56) 8 FLE))%bool
                    | None => false end
        | None => false end
      else
        (CBA.exit_base_chk GT.NF RETPC c ps && Nat.ltb 53 (CC.cp_nx c)
         && match CHA.retire_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS []) with Some fle => expr_eqb fle FLE | None => false end
         && has cells (KWord (SA FLE 0) 1 (ELit 0))
         && ((Nat.eqb i 3 && CBA.regions_eqb (CC.cp_F c) CPF3 && has cells (KWord (SA PE 208) 1 (ELit STSHORT)) && CL.ps_reg_is ps 10 (EAlu Instr.ALU_ADD PSE (ELit 1)) && has cells (KWord (SA PE 211) 1 (ELit 1)))
             || (Nat.eqb i 4 && CBA.regions_eqb (CC.cp_F c) CPF4 && CL.ps_reg_is ps 10 (pexp NLIT) && has cells (KWord (SA PE 211) 1 (ELit 1))
                 && ((CBA.has_range cells (EVar 34) 0 0 && has cells (KWord (SA PE 208) 1 (ELit 2))) || (CBA.has_range cells (EVar 34) 1 1024 && has cells (KWord (SA PE 208) 1 (ELit 7)))))
             || (Nat.leb 8 i && Nat.leb i 10 && CBA.regions_eqb (CC.cp_F c) CPF4 && CL.ps_reg_is ps 10 PLE && has cells (KWord (SA PE 211) 1 (ELit 0))
                 && has cells (KWord (SA PE 208) 1 (EVar 35)))))%bool
  end.
